const ZONE_OF: Record<string, number> = { zr: 1, zc: 2, zi: 3 };

// 介面的按鈕 → 實驗線的工具代號（規則 9：按鈕寫進資料的東西照實驗線）。路、公共設施是一組：按鈕下面那一排選的是哪一種
